#|GATV2_GRID = [
#|    {"hidden": 64, "layers": 2, "lr": 0.005},
#|    {"hidden": 128, "layers": 2, "lr": 0.005},
#|    {"hidden": 64, "layers": 3, "lr": 0.005},
