#|@@@@FILE: requirements.txt
#|# XAI-AMLBench  -  ONE file to install everything for local development
#|#
#|#     pip install -r requirements.txt          (or run:  bash install_all_requirements_v2.sh   -> does it all, fast)
#|#
#|# It only INCLUDES the per-service files below, so nothing is listed twice. Those files stay separate on purpose:
#|# each Docker image installs just its own service's packages (the backend image must not download PyTorch).
#|#
#|# Not in this file (needs a special source, the install script handles both):
#|#   torch==2.4.1   CPU build:  pip install torch==2.4.1 --index-url https://download.pytorch.org/whl/cpu
#|#   vllm           GPU only; it lives inside the xai-narrative-api Docker image
#|
#|numpy<2            # PyTorch 2.4.1 was built for NumPy 1.x (the Docker image uses 1.26)
#|
#|-r aml_synth/requirements.txt
#|-r gnn_aml_core/requirements.txt
#|-r backend/requirements.txt
#|-r xai_explainer/requirements.txt
#|@@@@END
#|@@@@FILE: run_local.py
#|#!/usr/bin/env python3
#|"""
#|run_local.py  -  run the whole application from your Python venv, with NO Docker image builds and NO downloads.
#|
#|The infrastructure (Postgres, Redis, immudb, ...) stays in the Docker containers you already have. The four application
#|services run straight from ~/Desktop/XAI-AMLBench/.venv and frontend/node_modules:
#|
#|    GNN model service   :8001   (loads ./models/gnn_model.pt)
#|    narrative service   :8002   (CPU, validated template narratives)
#|    backend API         :8000
#|    website             :3000   -> open http://localhost:3000
#|
#|    python3 run_local.py                # start everything, Ctrl+C stops everything
#|    python3 run_local.py --dry-run      # show what would run, start nothing
#|    python3 run_local.py --no-frontend  # only the three APIs
#|    python3 run_local.py --stop         # stop leftovers from an earlier run (e.g. the terminal was closed)
#|
#|Needs (once):   docker compose -f docker-compose.yml -f docker-compose.local.yml up -d database redis-feature-cache immudb-audit-ledger
#|Logs:           ./logs/gnn.log, xai.log, backend.log, frontend.log
#|"""
#|import argparse
#|import os
#|import signal
#|import socket
#|import subprocess
#|import sys
#|import time
