#|LOGS = ROOT / "logs"
#|PIDFILE = LOGS / "run_local.pids"
#|INFRA = {"Postgres": 15432, "Redis": 16379, "immudb (audit ledger)": 13322}
#|
#|
#|def read_env(path: Path) -> dict:
#|    env = {}
#|    if path.exists():
